-- One source: public.documentations. Meeting tables extend its original bigint ID.
create schema meeting_private;
revoke all on schema meeting_private from public,anon;grant usage on schema meeting_private to authenticated;
create table meeting_private.backups(id bigint generated always as identity primary key,created_at timestamptz default now(),data jsonb);
alter table meeting_private.backups enable row level security;revoke all on meeting_private.backups from public,anon,authenticated;
insert into meeting_private.backups(data) select jsonb_build_object('policies',(select jsonb_agg(to_jsonb(p)) from pg_policies p where schemaname='public' and tablename='documentations'),'count',(select count(*) from public.documentations),'hash',(select md5(coalesce(string_agg(to_jsonb(d)::text,'|' order by id),'')) from public.documentations d));
create table public.meeting_minutes(documentation_id bigint primary key references public.documentations(id),kind text not null check(kind in('weekly','teachers','students','assistant')),departments text[] not null default '{}',starts_at time,ends_at time,chair_id uuid references public.profiles(id),chair_name text not null default '',secretary_id uuid references public.profiles(id),secretary_name text not null default '',meeting_number text not null default '',classes jsonb not null default '[]',notes text not null default '',supervisors text[] not null default '{}',version integer not null default 1,is_test boolean not null default false,published_at timestamptz,check(ends_at>starts_at));
create table public.meeting_participants(id uuid primary key,documentation_id bigint not null references public.meeting_minutes(documentation_id),user_id uuid references public.profiles(id),name text not null check(length(btrim(name)) between 1 and 300),job_title text not null default '',department text not null default '',attendance text not null check(attendance in('unset','present','absent')),absence_reason text not null default '',share_absent boolean not null default false,position integer not null);
create unique index meeting_unique_account on public.meeting_participants(documentation_id,user_id) where user_id is not null;
create index meeting_participant_user on public.meeting_participants(user_id,documentation_id);
create table public.meeting_agenda(id uuid primary key,documentation_id bigint not null references public.meeting_minutes(documentation_id),position integer not null,title text not null,discussion text not null default '',goal text not null default '',responsible_id uuid references public.profiles(id),responsible_name text not null default '');
create table public.meeting_recommendations(id uuid primary key,documentation_id bigint not null references public.meeting_minutes(documentation_id),position integer not null,text text not null,responsible_id uuid references public.profiles(id),responsible_name text not null default '',target_date date,state text not null default 'not_started' check(state in('not_started','progress','done')),execution_notes text not null default '',version integer not null default 1,updated_at timestamptz not null default now());
create index meeting_rec_document on public.meeting_recommendations(documentation_id);
create index meeting_agenda_document on public.meeting_agenda(documentation_id);
create table public.meeting_links(documentation_id bigint not null references public.meeting_minutes(documentation_id),tag_id bigint not null references public.school_tags(id),primary key(documentation_id,tag_id));
create table public.meeting_initiative_links(documentation_id bigint not null references public.meeting_minutes(documentation_id),initiative_id bigint not null references public.documentations(id),primary key(documentation_id,initiative_id));
create index meeting_initiative_target on public.meeting_initiative_links(initiative_id,documentation_id);
create index meeting_link_tag on public.meeting_links(tag_id,documentation_id);
create table public.meeting_files(documentation_id bigint not null references public.meeting_minutes(documentation_id),path text not null,bucket text not null check(bucket='school-meeting-files'),name text not null,kind text not null check(kind in('photo','pdf','word')),primary key(documentation_id,path));
create table public.meeting_notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references public.profiles(id),documentation_id bigint not null references public.meeting_minutes(documentation_id),message text not null,created_at timestamptz default now(),read_at timestamptz,unique(recipient_id,documentation_id));
create index meeting_notifications_user on public.meeting_notifications(recipient_id,created_at desc);
create table meeting_private.operations(actor uuid not null,request uuid not null,payload jsonb not null,result jsonb not null,primary key(actor,request));
create table meeting_private.history(id bigint generated always as identity primary key,documentation_id bigint not null,actor uuid not null,action text not null,before_data jsonb,after_data jsonb,created_at timestamptz default now());
alter table meeting_private.operations enable row level security;alter table meeting_private.history enable row level security;revoke all on meeting_private.operations,meeting_private.history from public,anon,authenticated;
create function meeting_private.member() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.profiles where id=auth.uid())$$;
create function meeting_private.edit(doc bigint) returns boolean language sql stable security definer set search_path='' as $$select meeting_private.member() and exists(select 1 from public.documentations d where d.id=doc and d.activity_type='اجتماع' and d.deleted_at is null and (d.created_by=auth.uid() or documentation_private.can_manage()))$$;
create function meeting_private.read(doc bigint) returns boolean language sql stable security definer set search_path='' as $$select meeting_private.member() and exists(select 1 from public.documentations d join public.meeting_minutes m on m.documentation_id=d.id where d.id=doc and d.deleted_at is null and (d.created_by=auth.uid() or documentation_private.can_manage() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('principal','assistant_principal') and (p.school_access='all' or exists(select 1 from public.observation_access a where a.user_id=p.id and a.department=any(m.departments) and a.can_edit))) or d.status='published' and exists(select 1 from public.meeting_participants p where p.documentation_id=d.id and p.user_id=auth.uid() and (p.attendance='present' or p.attendance='absent' and p.share_absent))))$$;
-- Additional restrictive guards prevent legacy broad policies or direct edits leaking meetings.
create policy meeting_visibility_guard on public.documentations as restrictive for select to authenticated using(activity_type is distinct from 'اجتماع' or meeting_private.read(id));
create policy meeting_participant_read on public.documentations for select to authenticated using(activity_type='اجتماع' and meeting_private.read(id));
create policy meeting_insert_rpc_only on public.documentations as restrictive for insert to authenticated with check(activity_type is distinct from 'اجتماع');
create policy meeting_update_rpc_only on public.documentations as restrictive for update to authenticated using(activity_type is distinct from 'اجتماع') with check(activity_type is distinct from 'اجتماع');
do $$declare tab text;begin foreach tab in array array['meeting_minutes','meeting_participants','meeting_agenda','meeting_recommendations','meeting_links','meeting_initiative_links','meeting_files'] loop execute format('alter table public.%I enable row level security',tab);execute format('revoke all on public.%I from public,anon,authenticated',tab);execute format('grant select on public.%I to authenticated',tab);execute format('create policy meeting_read on public.%I for select to authenticated using(meeting_private.read(documentation_id))',tab);end loop;end$$;
alter table public.meeting_notifications enable row level security;revoke all on public.meeting_notifications from public,anon,authenticated;grant select on public.meeting_notifications to authenticated;create policy notice_own on public.meeting_notifications for select to authenticated using(recipient_id=auth.uid() and meeting_private.read(documentation_id));
create function meeting_private.catalog() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not meeting_private.member() then raise exception 'يرجى تسجيل الدخول.' using errcode='42501';end if;return jsonb_build_object('profile',(select jsonb_build_object('id',id,'full_name',full_name,'department',department,'role',role) from public.profiles where id=auth.uid()),'staff',coalesce((select jsonb_agg(jsonb_build_object('key',p.id::text,'user_id',p.id,'name',p.full_name,'job_title',coalesce(p.job_title,''),'departments',case when cardinality(p.departments)>0 then p.departments else array_remove(array[p.department],'') end,'role',p.role) order by p.full_name) from public.profiles p where nullif(btrim(p.full_name),'') is not null),'[]') || coalesce((select jsonb_agg(jsonb_build_object('key','manual:'||t.id,'user_id',null,'name',t.full_name,'job_title',coalesce(t.job_title,''),'departments',case when cardinality(t.departments)>0 then t.departments else array[t.department] end,'role','')) from public.observation_teachers t where t.active and t.user_id is null),'[]'),'tags',(select coalesce(jsonb_agg(t order by kind,name),'[]') from public.school_tags t),'initiatives',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',activity)),'[]') from public.documentations where activity_type='مبادرة' and deleted_at is null and (created_by=auth.uid() or documentation_private.can_manage())),'classes',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'grade',grade,'section',section) order by name),'[]') from public.building_locations where type='classroom' and active));end$$;
create function meeting_private.bundle(doc bigint) returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not meeting_private.read(doc) then raise exception 'لا تملكين صلاحية عرض المحضر.' using errcode='42501';end if;return jsonb_build_object('document',(select to_jsonb(d) from public.documentations d where id=doc),'meeting',(select to_jsonb(m) from public.meeting_minutes m where documentation_id=doc),'participants',(select coalesce(jsonb_agg(p order by position),'[]') from public.meeting_participants p where documentation_id=doc),'agenda',(select coalesce(jsonb_agg(a order by position),'[]') from public.meeting_agenda a where documentation_id=doc),'recommendations',(select coalesce(jsonb_agg(a order by position),'[]') from public.meeting_recommendations a where documentation_id=doc),'links',(select coalesce(jsonb_agg(t order by t.kind,t.name),'[]') from public.meeting_links l join public.school_tags t on t.id=l.tag_id where l.documentation_id=doc),'initiatives',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'name',d.activity)),'[]') from public.meeting_initiative_links l join public.documentations d on d.id=l.initiative_id where l.documentation_id=doc),'files',(select coalesce(jsonb_agg(f order by path),'[]') from public.meeting_files f where documentation_id=doc),'can_edit',meeting_private.edit(doc));end$$;
create function meeting_private.save(payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();req uuid:=(payload->>'request_id')::uuid;doc bigint:=(payload->>'id')::bigint;old_doc public.documentations;m public.meeting_minutes;v jsonb;p jsonb;f jsonb;tag_ids bigint[];depts text[];kind text:=payload->>'kind';publish boolean:=coalesce((payload->>'publish')::boolean,false);test_mode boolean:=coalesce((payload->>'is_test')::boolean,false);prior record;before_bundle jsonb;ename text;ejob text;edep text;position integer;state text;rid uuid;rec public.meeting_recommendations;linked_projects jsonb;linked_committees jsonb;v_details jsonb;result jsonb;
begin
 if not meeting_private.member() then raise exception 'هذه الخدمة للمستخدمات المخولات.' using errcode='42501';end if;
 if req is null or jsonb_typeof(payload)<>'object' or length(payload::text)>400000 then raise exception 'بيانات المحضر غير صالحة.';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||req::text,0));select * into prior from meeting_private.operations where actor=uid and request=req;if found then if prior.payload<>payload then raise exception 'محاولة حفظ مستخدمة لبيانات مختلفة.';end if;return prior.result;end if;
 if doc is not null then
 select * into old_doc from public.documentations where id=doc for update;select * into m from public.meeting_minutes where documentation_id=doc;
 if m.documentation_id is null or not meeting_private.edit(doc) then raise exception 'لا تملكين صلاحية تعديل المحضر.' using errcode='42501';end if;
 if m.version is distinct from (payload->>'version')::integer then raise exception 'تغيّر المحضر؛ افتحي أحدث نسخة قبل التعديل.';end if;
 before_bundle:=meeting_private.bundle(doc);test_mode:=m.is_test;if old_doc.status='published' and not publish then raise exception 'المحضر المنشور لا يعود مسودة عند التعديل.';end if;
 end if;
 if kind not in('weekly','teachers','students','assistant') or kind is null or length(btrim(coalesce(payload->>'title',''))) not between 1 and 300 or (payload->>'date') !~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' or payload->>'date' is null then raise exception 'حددي نوع الاجتماع وعنوانه وتاريخه.';end if;
 depts:=array(select jsonb_array_elements_text(coalesce(payload->'departments','[]')));if cardinality(depts)>20 then raise exception 'راجعي الأقسام.';end if;
 if exists(select 1 from unnest(depts) x where not exists(select 1 from public.profiles where department=x or x=any(departments))) then raise exception 'اختاري الأقسام المسجلة في البوابة.';end if;
 if publish and (nullif(payload->>'starts_at','') is null or nullif(payload->>'ends_at','') is null or (payload->>'ends_at')::time<=(payload->>'starts_at')::time or nullif(btrim(payload->>'location'),'') is null or nullif(btrim(payload->>'chair_name'),'') is null or (kind<>'students' and nullif(btrim(payload->>'secretary_name'),'') is null)) then raise exception 'أكملي الوقت والمكان ورئيسة الاجتماع ومقررته قبل النشر.';end if;
 if kind='weekly' and cardinality(depts)<>1 or kind='assistant' and cardinality(depts)<>1 then raise exception 'اختاري قسمًا واحدًا لهذا النوع.';end if;
 if publish and kind='students' and jsonb_array_length(coalesce(payload->'classes','[]'))=0 then raise exception 'حددي الصف والشعبة لاجتماع الطالبات.';end if;
 if jsonb_typeof(coalesce(payload->'classes','[]'))<>'array' or exists(select 1 from jsonb_array_elements(coalesce(payload->'classes','[]')) c where not exists(select 1 from public.building_locations l where l.id=(c->>'id')::uuid and l.type='classroom' and l.active and l.name=c->>'name')) then raise exception 'اختاري الصف والشعبة من بيانات المدرسة الفعلية.';end if;
 if kind='assistant' and (not exists(select 1 from public.profiles where id=(payload->>'chair_id')::uuid and role='assistant_principal') or not exists(select 1 from jsonb_array_elements(coalesce(payload->'participants','[]')) jv join public.profiles pr on pr.id=(jv->>'user_id')::uuid where (pr.role in('first_teacher','coordinator') or pr.job_title ~ '(الأولى|اولى|أولى|منسقة|منقسة)') and (pr.department=any(depts) or pr.departments&&depts))) then raise exception 'اختاري المديرة المساعدة والمعلمة الأولى أو المنسقة المرتبطة بالقسم.';end if;
 if jsonb_typeof(coalesce(payload->'supervisors','[]'))<>'array' or exists(select 1 from jsonb_array_elements_text(coalesce(payload->'supervisors','[]')) s where s not in('assistant','aisha','hiba','services')) then raise exception 'اختيار إشراف غير صالح.';end if;
 if nullif(payload->>'chair_id','') is not null and not exists(select 1 from public.profiles where id=(payload->>'chair_id')::uuid and full_name=payload->>'chair_name') then raise exception 'راجعي حساب واسم رئيسة الاجتماع.';end if;
 if nullif(payload->>'secretary_id','') is not null and not exists(select 1 from public.profiles where id=(payload->>'secretary_id')::uuid and full_name=payload->>'secretary_name') then raise exception 'راجعي حساب واسم المقررة.';end if;
 if jsonb_typeof(payload->'participants') is distinct from 'array' or jsonb_array_length(payload->'participants')>250 or jsonb_typeof(payload->'agenda') is distinct from 'array' or jsonb_array_length(payload->'agenda')>80 or jsonb_typeof(payload->'recommendations') is distinct from 'array' or jsonb_array_length(payload->'recommendations')>80 then raise exception 'راجعي جداول المحضر.';end if;
 if publish and (jsonb_array_length(payload->'participants')=0 or exists(select 1 from jsonb_array_elements(payload->'participants') jv where coalesce(jv->>'attendance','unset')='unset') or jsonb_array_length(payload->'agenda')=0) then raise exception 'سجلي حالة حضور جميع المشاركات وأضيفي بنود جدول الأعمال قبل النشر.';end if;
 if jsonb_array_length(coalesce(payload->'files','[]'))>15 or jsonb_typeof(coalesce(payload->'files','[]'))<>'array' then raise exception 'راجعي المرفقات.';end if;
 for f in select * from jsonb_array_elements(coalesce(payload->'files','[]')) loop
 if f->>'bucket' is distinct from 'school-meeting-files' or f->>'kind' not in('photo','pdf','word') or length(coalesce(f->>'name','')) not between 1 and 250 then raise exception 'مرجع مرفق غير صالح.';end if;
 if not exists(select 1 from public.meeting_files mf where mf.documentation_id=doc and mf.path=f->>'path' and mf.name=f->>'name' and mf.kind=f->>'kind') and (coalesce(f->>'path','') !~ ('^'||uid||'/'||req||'/[a-f0-9-]{36}\.(jpg|pdf|doc|docx)$') or not exists(select 1 from storage.objects o where o.bucket_id='school-meeting-files' and o.name=f->>'path' and coalesce(o.owner_id,o.owner::text)=uid::text and (o.metadata->>'size')::bigint between 1 and 8388608 and (case f->>'kind' when 'photo' then o.metadata->>'mimetype'='image/jpeg' when 'pdf' then o.metadata->>'mimetype'='application/pdf' else o.metadata->>'mimetype' in('application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document') end))) then raise exception 'لم يكتمل رفع المرفق أو لا تملكينه.';end if;
 end loop;
 tag_ids:=array(select distinct value::bigint from jsonb_array_elements_text(coalesce(payload->'tag_ids','[]')));if exists(select 1 from unnest(tag_ids) t where not exists(select 1 from public.school_tags where id=t)) then raise exception 'الارتباط غير موجود في القوائم المعتمدة.';end if;
 select coalesce(jsonb_agg(name),'[]') into linked_projects from public.school_tags tag where tag.id=any(tag_ids) and tag.kind='project' and tag.name<>'أنتِ تستحقين الشكر';select coalesce(jsonb_agg(name),'[]') into linked_committees from public.school_tags tag where tag.id=any(tag_ids) and tag.kind='committee';
 v_details:=jsonb_build_object('type','اجتماع','activity',payload->>'title','department',array_to_string(depts,' • '),'date',payload->>'date','reportPreparedBy',(select full_name from public.profiles where id=coalesce(old_doc.created_by,uid)),'projects',linked_projects,'committees',linked_committees,'areas',coalesce(payload->'areas','[]'),'academicYear',payload->>'academic_year','is_test',test_mode,'is_draft',not publish,'meeting',true);
 if doc is null then insert into public.documentations(created_by,request_id,activity,activity_type,department,activity_date,semester,location,executor,status,details,projects,committees,documentation_area) values(uid,req,payload->>'title','اجتماع',array_to_string(depts,' • '),(payload->>'date')::date,payload->>'semester',payload->>'location',v_details->>'reportPreparedBy',case when publish then 'published' else 'draft' end,v_details,array_to_string(array(select jsonb_array_elements_text(linked_projects)),' • '),array_to_string(array(select jsonb_array_elements_text(linked_committees)),' • '),array_to_string(array(select jsonb_array_elements_text(coalesce(payload->'areas','[]'))),' • ')) returning id into doc;
 else update public.documentations set activity=payload->>'title',department=array_to_string(depts,' • '),activity_date=(payload->>'date')::date,semester=payload->>'semester',location=payload->>'location',status=case when publish then 'published' else 'draft' end,details=v_details,projects=array_to_string(array(select jsonb_array_elements_text(linked_projects)),' • '),committees=array_to_string(array(select jsonb_array_elements_text(linked_committees)),' • '),documentation_area=array_to_string(array(select jsonb_array_elements_text(coalesce(payload->'areas','[]'))),' • '),last_edit_request=req where id=doc;end if;
 insert into public.meeting_minutes(documentation_id,kind,departments,starts_at,ends_at,chair_id,chair_name,secretary_id,secretary_name,meeting_number,classes,notes,supervisors,version,is_test,published_at) values(doc,kind,depts,nullif(payload->>'starts_at','')::time,nullif(payload->>'ends_at','')::time,nullif(payload->>'chair_id','')::uuid,payload->>'chair_name',nullif(payload->>'secretary_id','')::uuid,coalesce(payload->>'secretary_name',''),coalesce(payload->>'meeting_number',''),coalesce(payload->'classes','[]'),coalesce(payload->>'notes',''),array(select jsonb_array_elements_text(coalesce(payload->'supervisors','[]'))),coalesce(m.version,0)+1,test_mode,case when publish then coalesce(m.published_at,now()) end) on conflict(documentation_id) do update set kind=excluded.kind,departments=excluded.departments,starts_at=excluded.starts_at,ends_at=excluded.ends_at,chair_id=excluded.chair_id,chair_name=excluded.chair_name,secretary_id=excluded.secretary_id,secretary_name=excluded.secretary_name,meeting_number=excluded.meeting_number,classes=excluded.classes,notes=excluded.notes,supervisors=excluded.supervisors,version=excluded.version,published_at=excluded.published_at;
 delete from public.meeting_participants where documentation_id=doc;position:=0;
 for p in select * from jsonb_array_elements(payload->'participants') loop
 position:=position+1;ename:=p->>'name';ejob:=coalesce(p->>'job_title','');edep:=coalesce(p->>'department','');
 if nullif(p->>'user_id','') is not null then select full_name,coalesce(job_title,''),coalesce(department,'') into ename,ejob,edep from public.profiles where id=(p->>'user_id')::uuid;if not found then raise exception 'حساب مشاركة غير موجود.';end if;end if;
 insert into public.meeting_participants values((p->>'id')::uuid,doc,nullif(p->>'user_id','')::uuid,ename,ejob,edep,coalesce(p->>'attendance','unset'),coalesce(p->>'absence_reason',''),coalesce((p->>'share_absent')::boolean,false),position);
 end loop;
 if exists(select 1 from public.meeting_participants where documentation_id=doc group by lower(regexp_replace(btrim(name),'\s+',' ','g')),department having count(*)>1) then raise exception 'لا تكرري المشاركة في الاجتماع نفسه.';end if;
 delete from public.meeting_agenda where documentation_id=doc;position:=0;
 for p in select * from jsonb_array_elements(payload->'agenda') loop position:=position+1;if nullif(btrim(p->>'title'),'') is null then raise exception 'اكتبي عنوان بند جدول الأعمال.';end if;insert into public.meeting_agenda values((p->>'id')::uuid,doc,position,p->>'title',coalesce(p->>'discussion',''),coalesce(p->>'goal',''),nullif(p->>'responsible_id','')::uuid,coalesce(p->>'responsible_name',''));end loop;
 -- Keep recommendation execution history and prevent stale meeting edits overwriting progress.
 delete from public.meeting_recommendations where documentation_id=doc and id not in(select (jv->>'id')::uuid from jsonb_array_elements(payload->'recommendations') jv);
 position:=0;for p in select * from jsonb_array_elements(payload->'recommendations') loop position:=position+1;rid:=(p->>'id')::uuid;select * into rec from public.meeting_recommendations where id=rid;if rec.id is not null and rec.documentation_id<>doc then raise exception 'معرّف توصية غير صالح.';end if;
 if nullif(btrim(p->>'text'),'') is null then raise exception 'اكتبي نص التوصية.';end if;
 if nullif(p->>'responsible_id','') is not null and not exists(select 1 from public.meeting_participants where documentation_id=doc and user_id=(p->>'responsible_id')::uuid and (attendance='present' or attendance='absent' and share_absent)) and (p->>'responsible_id')::uuid<>coalesce(old_doc.created_by,uid) then raise exception 'أضيفي المسؤولة عن التنفيذ ضمن المشاركات المسموح لهن بقراءة المحضر.';end if;
 if rec.id is not null and rec.version is distinct from (p->>'version')::integer then raise exception 'تغيّرت متابعة توصية؛ افتحي النسخة الأحدث.';end if;
 state:=coalesce(p->>'state','not_started');insert into public.meeting_recommendations values(rid,doc,position,p->>'text',nullif(p->>'responsible_id','')::uuid,coalesce(p->>'responsible_name',''),nullif(p->>'target_date','')::date,state,coalesce(p->>'execution_notes',''),coalesce(rec.version,0)+1,now()) on conflict(id) do update set position=excluded.position,text=excluded.text,responsible_id=excluded.responsible_id,responsible_name=excluded.responsible_name,target_date=excluded.target_date,state=excluded.state,execution_notes=excluded.execution_notes,version=excluded.version,updated_at=excluded.updated_at;
 end loop;
 delete from public.meeting_links where documentation_id=doc;insert into public.meeting_links select doc,unnest(tag_ids);
 -- Canonical IDs include every selected tag. Avoid applying the separate recognition form's validation to a meeting.
 insert into public.documentation_tags select doc,unnest(tag_ids) on conflict do nothing;
 delete from public.meeting_initiative_links where documentation_id=doc;
 for p in select * from jsonb_array_elements(coalesce(payload->'initiative_ids','[]')) loop
 if not exists(select 1 from public.documentations where id=(p#>>'{}')::bigint and activity_type='مبادرة' and deleted_at is null and (created_by=uid or documentation_private.can_manage())) then raise exception 'المبادرة غير متاحة ضمن صلاحياتكِ.';end if;insert into public.meeting_initiative_links values(doc,(p#>>'{}')::bigint) on conflict do nothing;end loop;
 delete from public.meeting_files where documentation_id=doc;insert into public.meeting_files select doc,asset->>'path',asset->>'bucket',asset->>'name',asset->>'kind' from jsonb_array_elements(coalesce(payload->'files','[]')) asset;
 if publish and not test_mode then insert into public.meeting_notifications(recipient_id,documentation_id,message) select distinct user_id,doc,'تم توثيق محضر اجتماع بعنوان '||(payload->>'title')||' بتاريخ '||(payload->>'date')||'، ويمكنكِ الاطلاع على تفاصيل الاجتماع والتوصيات من صفحة اجتماعاتي.' from public.meeting_participants where documentation_id=doc and user_id is not null and (attendance='present' or attendance='absent' and share_absent) on conflict(recipient_id,documentation_id) do nothing;end if;
 result:=meeting_private.bundle(doc);insert into meeting_private.history(documentation_id,actor,action,before_data,after_data) values(doc,uid,'save',before_bundle,result);insert into meeting_private.operations values(uid,req,payload,result);return result;
end$$;
create function meeting_private.follow(rec_id uuid,expected_version integer,new_state text,notes text,request uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.meeting_recommendations;before_rec jsonb;v jsonb;prior record;p jsonb:=jsonb_build_object('rec',rec_id,'version',expected_version,'state',new_state,'notes',notes);begin
 if not meeting_private.member() or request is null then raise exception 'غير مصرح.' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||request::text,0));select * into prior from meeting_private.operations where actor=auth.uid() and meeting_private.operations.request=follow.request;if found then if prior.payload<>p then raise exception 'محاولة مكررة مختلفة.';end if;return prior.result;end if;
 select * into r from public.meeting_recommendations where id=rec_id for update;if not found or not meeting_private.read(r.documentation_id) or not (meeting_private.edit(r.documentation_id) or r.responsible_id=auth.uid()) then raise exception 'لا تملكين صلاحية متابعة التوصية.' using errcode='42501';end if;if r.version<>expected_version then raise exception 'التوصية تغيّرت؛ أعيدي تحميلها.';end if;if new_state not in('not_started','progress','done') or length(coalesce(notes,''))>20000 then raise exception 'بيانات المتابعة غير صالحة.';end if;before_rec:=to_jsonb(r);update public.meeting_recommendations set state=new_state,execution_notes=coalesce(notes,''),version=version+1,updated_at=now() where id=rec_id returning * into r;v:=to_jsonb(r);insert into meeting_private.history(documentation_id,actor,action,before_data,after_data) values(r.documentation_id,auth.uid(),'follow',before_rec,v);insert into meeting_private.operations values(auth.uid(),request,p,v);return v;end$$;
create function meeting_private.list() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('document',to_jsonb(d),'meeting',to_jsonb(m),'attendance',(select attendance from public.meeting_participants p where p.documentation_id=d.id and p.user_id=auth.uid()),'links',(select coalesce(jsonb_agg(t),'[]') from public.meeting_links l join public.school_tags t on t.id=l.tag_id where l.documentation_id=d.id),'initiatives',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',x.activity)),'[]') from public.meeting_initiative_links l join public.documentations x on x.id=l.initiative_id where l.documentation_id=d.id),'can_edit',meeting_private.edit(d.id),'present',(select count(*) from public.meeting_participants where documentation_id=d.id and attendance='present'),'absent',(select count(*) from public.meeting_participants where documentation_id=d.id and attendance='absent')) order by d.activity_date desc,d.id desc),'[]') from public.documentations d join public.meeting_minutes m on m.documentation_id=d.id where meeting_private.read(d.id) and not m.is_test$$;
create function meeting_private.mark_read(notice uuid) returns void language sql security definer set search_path='' as $$update public.meeting_notifications set read_at=coalesce(read_at,now()) where id=notice and recipient_id=auth.uid() and meeting_private.read(documentation_id)$$;
create function meeting_private.file_read(path text) returns boolean language sql stable security definer set search_path='' as $$select meeting_private.member() and (split_part(path,'/',1)=auth.uid()::text or exists(select 1 from public.meeting_files f where f.path=file_read.path and meeting_private.read(f.documentation_id)))$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('school-meeting-files','school-meeting-files',false,8388608,array['image/jpeg','application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document']);
create policy meeting_file_upload on storage.objects for insert to authenticated with check(bucket_id='school-meeting-files' and meeting_private.member() and split_part(name,'/',1)=auth.uid()::text and name~'^[a-f0-9-]{36}/[a-f0-9-]{36}/[a-f0-9-]{36}\.(jpg|pdf|doc|docx)$');
create policy meeting_file_read on storage.objects for select to authenticated using(bucket_id='school-meeting-files' and meeting_private.file_read(name));
-- Public invoker wrappers; every privileged helper checks the actual signed-in account.
create function public.meeting_catalog() returns jsonb language sql stable security invoker set search_path='' as $$select meeting_private.catalog()$$;
create function public.meeting_bundle(doc bigint) returns jsonb language sql stable security invoker set search_path='' as $$select meeting_private.bundle(doc)$$;
create function public.meeting_save(payload jsonb) returns jsonb language sql security invoker set search_path='' as $$select meeting_private.save(payload)$$;
create function public.meeting_follow(rec_id uuid,expected_version integer,new_state text,notes text,request uuid) returns jsonb language sql security invoker set search_path='' as $$select meeting_private.follow(rec_id,expected_version,new_state,notes,request)$$;
create function public.meeting_list() returns jsonb language sql stable security invoker set search_path='' as $$select meeting_private.list()$$;
create function public.meeting_mark_read(notice uuid) returns void language sql security invoker set search_path='' as $$select meeting_private.mark_read(notice)$$;
do $$declare fn record;begin for fn in select proc.oid::regprocedure f from pg_proc proc join pg_namespace n on n.oid=proc.pronamespace where n.nspname='meeting_private' or n.nspname='public' and proc.proname like 'meeting_%' loop execute format('revoke all on function %s from public,anon',fn.f);execute format('grant execute on function %s to authenticated',fn.f);end loop;end$$;
